-- ========================================================
-- CAPSTONE PROJECT: Formula 1 Strategy & Performance Audit
-- COMPANY: Apex Racing Analytics
-- ========================================================
create database f1_project;
use f1_project;

-- --------------------------------------------------------
-- PART 1: TABLE CREATION (Schema Architecture)
-- --------------------------------------------------------
DROP TABLE IF EXISTS pit_stops;
DROP TABLE IF EXISTS results;
DROP TABLE IF EXISTS races;
DROP TABLE IF EXISTS drivers;
DROP TABLE IF EXISTS constructors;

CREATE TABLE constructors (
    constructorId INT PRIMARY KEY,
    constructorRef VARCHAR(50) NOT NULL,
    name VARCHAR(100) NOT NULL,
    nationality VARCHAR(50),
    url VARCHAR(255)
);

CREATE TABLE drivers (
    driverId INT PRIMARY KEY,
    driverRef VARCHAR(50) NOT NULL,
    number INT NULL,              -- Restored to INT
    code VARCHAR(10) NULL,
    forename VARCHAR(50) NOT NULL,
    surname VARCHAR(50) NOT NULL,
    dob DATE NULL,                -- Restored to DATE
    nationality VARCHAR(50),
    url VARCHAR(255)
);

CREATE TABLE races (
    raceId INT PRIMARY KEY,
    year INT NOT NULL,
    round INT NOT NULL,
    circuitId INT NOT NULL,
    name VARCHAR(100) NOT NULL,
    date DATE NOT NULL,
    time TIME NULL,               -- Restored to TIME
    url VARCHAR(255),
    fp1_date VARCHAR(20) NULL,
    fp1_time VARCHAR(20) NULL,
    fp2_date VARCHAR(20) NULL,
    fp2_time VARCHAR(20) NULL,
    fp3_date VARCHAR(20) NULL,
    fp3_time VARCHAR(20) NULL,
    quali_date VARCHAR(20) NULL,
    quali_time VARCHAR(20) NULL,
    sprint_date VARCHAR(20) NULL,
    sprint_time VARCHAR(20) NULL
);

CREATE TABLE results (
    resultId INT PRIMARY KEY,
    raceId INT NOT NULL,
    driverId INT NOT NULL,
    constructorId INT NOT NULL,
    number INT NULL,               -- Restored to INT
    grid INT NOT NULL,
    position INT NULL,             -- Restored to INT (Safe, only holds numbers or NULL)
    positionText VARCHAR(10) NOT NULL, -- Holds the 'R' and 'D' values
    positionOrder INT NOT NULL,
    points DECIMAL(5,2) NOT NULL,
    laps INT NOT NULL,
    time VARCHAR(50) NULL,
    milliseconds INT NULL,         -- Restored to INT
    fastestLap INT NULL,           -- Restored to INT
    `rank` INT NULL,               -- Restored to INT
    fastestLapTime VARCHAR(20) NULL,
    fastestLapSpeed DECIMAL(6,3) NULL, -- Restored to DECIMAL
    statusId INT NOT NULL,
    FOREIGN KEY (raceId) REFERENCES races(raceId),
    FOREIGN KEY (driverId) REFERENCES drivers(driverId),
    FOREIGN KEY (constructorId) REFERENCES constructors(constructorId)
);

CREATE TABLE pit_stops (
    raceId INT NOT NULL,
    driverId INT NOT NULL,
    stop INT NOT NULL,
    lap INT NOT NULL,
    time VARCHAR(20) NULL,
    duration VARCHAR(20) NULL,     -- Kept as VARCHAR due to formatting like "1:22.413"
    milliseconds INT NULL,         -- Restored to INT
    FOREIGN KEY (raceId) REFERENCES races(raceId),
    FOREIGN KEY (driverId) REFERENCES drivers(driverId)
);


-- --------------------------------------------------------
-- PART 2: DATA INSERTION
-- --------------------------------------------------------
use f1_project;

SET FOREIGN_KEY_CHECKS=0;






SET FOREIGN_KEY_CHECKS=1;


-- --------------------------------------------------------
-- PART 3: ANALYTICAL TASKS & QUERIES
-- --------------------------------------------------------
select * from constructors;
select * from drivers;
select * from pit_stops;
select * from races;
select * from results;

-- Question 1: All-Time Driver Victory Leaderboard
-- ●	Business Goal: The media team needs an all-time top 10 leaderboard of Formula 1 drivers based on total Grand Prix wins.
-- ●	Requirements: Return driverId, full name (combined forename and surname), nationality, and TotalWins. Sort by total wins descending, limiting to the top 10.

select d.driverId,concat(d.forename," ",d.surname) as `Full Name`, d.nationality, count(res.positionOrder) as `Total Wins`
from drivers as d
inner join
results as res on d.driverId=res.driverId
where res.positionOrder=1
group by d.driverId,d.forename,d.surname,d.nationality
order by `Total Wins` desc
limit 10;

# Lewis Hamilton is the GOAT with 105 Grand Prix wins

-- Question 2: Single-Season Team Performance Standings
-- ●	Business Goal: Evaluate constructor competitiveness in the 2023 season by ranking teams by total points scored.
-- ●	Requirements: Join results, constructors, and races. Filter for year = 2023, aggregate points using SUM(), and display team name alongside total points sorted highest to lowest.

select c.constructorId,c.name,sum(res.points) as `Total Points`
from constructors as c inner join results as res
on c.constructorId=res.constructorId
inner join races as rac on rac.raceId=res.raceId
where year=2023
group by c.constructorId,c.name
order by `Total Points` desc;

# Red Bull dominated 2023 with 790 points

-- Question 3: The "Comeback Kings"
-- ●	Business Goal: Highlight drivers who achieved extraordinary race wins starting from deep in the pack (grid position 10 or lower).
-- ●	Requirements: Retrieve the driver’s full name, race year, Grand Prix name, starting grid position (grid), and finishing position (positionOrder = 1). Filter for starting positions >= 10.

select d.driverId,concat(d.forename," ",d.surname) as `Full Name`,
rac.year,rac.name as `Grand Prix`,res.grid,res.positionOrder as `Final Position`
from drivers as d inner join results as res on
d.driverId = res.driverId
inner join races as rac on
rac.raceId = res.raceId
where res.grid>=10 and res.positionOrder=1
order by rac.year desc, res.grid desc;

# Max Verstappen is the driver who has achieved this feat for 3 times in a row recently

-- Question 4: Modern Pit Crew Efficiency Audit
-- ●	Business Goal: Pit strategy wins races. Rank constructors by their average pit stop speed (in seconds) for races in 2021 or later.
-- ●	Requirements: Convert milliseconds to seconds (milliseconds / 1000.0), calculate the average duration per constructor, count total pit stops, and filter for constructors with at least 20 recorded stops using a HAVING clause.

select c.constructorId,c.name,avg(p.milliseconds/1000) as `Average pitstop time`,
sum(p.stop) as `Total Stops`
from constructors as c inner join results as res
on c.constructorId=res.constructorId
inner join races as rac on res.raceId=rac.raceId
inner join pit_stops as p on p.raceId=rac.raceId
where rac.year>=2021
group by c.constructorId,c.name
having `Total Stops` >= 20;

# The company Audi and Cadillac have least amount of stops from 2021

-- Question 5: "Best of the Rest" (Subquery Challenge)
-- ●	Business Goal: Identify drivers who achieved great consistency with at least 5 podium finishes (top 3 finish), but NEVER won a single Grand Prix in their career.
-- ●	Requirements: Use a subquery with NOT IN (or NOT EXISTS) to exclude any driver who has a 1st place finish (positionOrder = 1), while grouping and counting podium finishes (<= 3).

select d.driverId,concat(d.forename," ",d.surname) as `Full Name`,c.name,count(positionOrder) as `Podium Finish`
from drivers as d inner join results as res on res.driverId=d.driverId
inner join constructors as c on res.constructorId=c.constructorId
where res.positionOrder <= 3 and d.driverId not in (
select d.driverId from drivers where res.positionOrder=1)
group by d.driverId,d.forename,d.surname,c.name
having `Podium Finish` >=5 
order by `Podium Finish` desc;




